//crating global emitter

const listeners = new Set();

export function onCraftGlobal(cb) {

  listeners.add(cb);
  return () => listeners.delete(cb);

}

export function emitCraftGlobal(recipe) {

  listeners.forEach((cb) => cb(recipe));
  console.debug("%c[CRAFTED]", "color: #4caf50", recipe.result.id);

}
