import { useEffect, useState, useRef } from "react";
import Pickup from "./components/InventorySlots/containers/Pickup";
import Screens from "./components/Screens";
import Tooltip from "./components/Tooltip";
import { AppProvider } from "./provider";
import Stopwatch from "./stopwatch";
import { onCraftGlobal } from "./events";

function App() {
  const [isPortrait, setIsPortrait] = useState(false);
  const stopwatchRef = useRef(null);
  const stopSoundRef = useRef(new Audio("/stop.mp3"));

  const START_RECIPES = [278, 798, 794, 942, 758, 868, 1116, 736];
  const STOP_RECIPES = [278, 798, 794, 942, 758, 868, 1116, 736];

  const [stopwatchStarted, setStopwatchStarted] = useState(false);
  const [craftedStopRecipes, setCraftedStopRecipes] = useState(new Set());

  // prevent right-click
  useEffect(() => {
    const handleContextMenu = (e) => e.preventDefault();
    document.addEventListener("contextmenu", handleContextMenu);
    return () => document.removeEventListener("contextmenu", handleContextMenu);
  }, []);

  //  portrait orientation
  useEffect(() => {
    const handleOrientationChange = () => {
      setIsPortrait(
        window.innerWidth < window.innerHeight && window.innerWidth < 1024
      );
    };
    handleOrientationChange();
    window.addEventListener("resize", handleOrientationChange);
    return () => window.removeEventListener("resize", handleOrientationChange);
  }, []);

  // crafting events
  useEffect(() => {
    const unsubscribe = onCraftGlobal((recipe) => {
      const id = recipe.result.id;

      // start stopwatch
      if (!stopwatchStarted && START_RECIPES.includes(id)) {
        stopwatchRef.current?.start();
        setStopwatchStarted(true);
      }

      //  track which have been crafted
      if (STOP_RECIPES.includes(id)) {
        setCraftedStopRecipes((prev) => {
          const updated = new Set(prev);
          updated.add(id);
          // if all are crafted, stop the stopwatch
          if (STOP_RECIPES.every((r) => updated.has(r))) {
            stopwatchRef.current?.stop();
            stopSoundRef.current.play().catch(() => {});
          }
          return updated;
        });
      }
    });

    return unsubscribe;
  }, [stopwatchStarted]);

  return (
    <main className="w-screen h-screen bg-black relative">
      <div
        className="absolute inset-0 bg-center bg-cover opacity-50 blur-xl"
        style={{
          backgroundImage:
            "url('https://i.ytimg.com/vi/mIROyJaMLFg/maxresdefault.jpg')",
        }}
      />

      <span className="absolute text-xs text-center text-pink-300 -translate-x-1/2 opacity-30 top-4 left-1/2">
        Source Code by <a href="https://github.com/EnhancedJax/minecraft-react-crafting">Jax</a>, additions by ArvieAll
      </span>

      <Stopwatch ref={stopwatchRef} />

      {isPortrait ? (
        <div className="absolute inset-0 flex flex-col gap-2 text-white bg-black flex-center bg-opacity-70 animate-pulse">
          <img
            src="crafting_table_front.png"
            alt="logo"
            className="w-12 h-12 pixelated"
          />
          <span className="text-xl">Please rotate your device!</span>
        </div>
      ) : (
        <AppProvider>
          <div className="flex w-screen h-screen gap-8 flex-center sm:flex-col xl:scale-75">
            <Screens />
            <Pickup />
            <Tooltip />
          </div>
        </AppProvider>
      )}
    </main>
  );
}

export default App;
