import { useState, useEffect, forwardRef, useImperativeHandle } from "react";

const Stopwatch = forwardRef(({ autoReset = true }, ref) => {
  const [time, setTime] = useState(0); // in milliseconds
  const [running, setRunning] = useState(false);

  useImperativeHandle(ref, () => ({
    start: () => setRunning(true),
    stop: () => setRunning(false),
    reset: () => setTime(0),
  }));

  useEffect(() => {
    if (!running) return;
    const interval = setInterval(() => setTime((t) => t + 10), 10); // update every 10ms
    return () => clearInterval(interval);
  }, [running]);

  const minutes = Math.floor(time / 60000);
  const seconds = Math.floor((time % 60000) / 1000);
  const tens = Math.floor((time % 1000) / 10);

  return (
    <div className="absolute top-32 left-1/2 -translate-x-1/2 text-3xl text-green-300">
      <span>{minutes.toString().padStart(2, "0")}</span>:
      <span>{seconds.toString().padStart(2, "0")}</span>.
      <span>{tens.toString().padStart(2, "0")}</span>
    </div>
  );
});

export default Stopwatch;
